WITH CONNECTION source AS ('bootstrap.servers'='127.0.0.1:19092','session.timeout.ms'='6000','heartbeat.interval.ms'='1000','socket.timeout.ms'='500'), CONNECTION destination AS ('bootstrap.servers'='127.0.0.1:29092','client.id'='lab-m2','linger.ms'='1500','request.timeout.ms'='1000','socket.timeout.ms'='500') INSERT INTO TOPIC 'output@destination' WITH (PARTITIONING = PRESERVE) SELECT * FROM TOPIC 'input@source' WITH (GROUP='explicit-group') WHERE PARTITION IN (0,1,2);
